const LANG_LABELS = { ja: "日本語", en: "English",};
const LangContext = createContext({ lang: "en", t: TRANSLATIONS.en });
const useLang = () => useContext(LangContext);

/* ══════════════════════════════════════════════════════
   Storage
══════════════════════════════════════════════════════ */
const STORAGE_KEY = "travel_notebooks_v4";
const LANG_KEY    = "travel_notebook_lang";

async function loadAllNotebooks() {
  try { const r = await window.storage.get(STORAGE_KEY); return r ? JSON.parse(r.value) : {}; }
  catch { return {}; }
}
async function saveAllNotebooks(d) {
  try { await window.storage.set(STORAGE_KEY, JSON.stringify(d)); } catch {}
}
async function loadLang() {
  try { const r = await window.storage.get(LANG_KEY); return r?.value || "en"; } catch { return "en"; }
}
async function saveLang(l) { try { await window.storage.set(LANG_KEY, l); } catch {} }

/* ══════════════════════════════════════════════════════
   Geo
══════════════════════════════════════════════════════ */
async function fetchCityName(lat, lng, lang) {
  const locale = lang === "zh" ? "zh" : lang === "ja" ? "ja" : "en";
  const res = await fetch(
    `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json&accept-language=${locale}`,
    { headers: { "User-Agent": "TravelNoteApp/4.0" } }
  );
  const data = await res.json();
  const a = data.address || {};

  const country = a.country_code?.toLowerCase() || "xx";
  const prefecture = a.state || a.province || "";
  const city = a.city || a.town || a.village || a.county || a.state_district || "Here";

  const normalize = (s) =>
    String(s).trim().toLowerCase().replace(/\s+/g, "-");
  
  const cityKey = `${normalize(country)}|${normalize(prefecture)}|${normalize(city)}`;

  return {
    country,
    prefecture,
    city,
    cityKey,
    lat,
    lng,
  };
}

/* ══════════════════════════════════════════════════════
   Palette — earthy tones to complement the meadow
══════════════════════════════════════════════════════ */
const PALETTES = [
  { spine: "#5a3a1a", cover: "#c8a878", text: "#1a0a00", accent: "#8b5e2a" },
  { spine: "#2a4a1a", cover: "#a8c880", text: "#0a1a00", accent: "#4a7a2a" },
  { spine: "#1a3a5a", cover: "#7ab0d8", text: "#001020", accent: "#2a6a9a" },
  { spine: "#5a1a1a", cover: "#c87878", text: "#1a0000", accent: "#8a2a2a" },
  { spine: "#4a3a1a", cover: "#c8b060", text: "#1a1000", accent: "#7a6020" },
  { spine: "#3a1a4a", cover: "#a878c8", text: "#100018", accent: "#6a2a8a" },
];

function getPalette(cityName) {
  let h = 0;
  for (let i = 0; i < cityName.length; i++) h = (h * 31 + cityName.charCodeAt(i)) & 0xffffffff;
  return PALETTES[Math.abs(h) % PALETTES.length];
}

/* ══════════════════════════════════════════════════════
   Language Switcher
══════════════════════════════════════════════════════ */
function LangSwitcher({ lang, onChange }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="lang-switcher" onMouseLeave={() => setOpen(false)}>
      <button className="lang-switcher__trigger" onClick={() => setOpen(o => !o)}>
        <span>◎</span>
        <span>{LANG_LABELS[lang]}</span>
        <span style={{ fontSize: 8, opacity: 0.6 }}>{open ? "▴" : "▾"}</span>
      </button>
      {open && (
        <div className="lang-switcher__dropdown">
          {Object.entries(LANG_LABELS).map(([code, label]) => (
            <button
              key={code}
              className={`lang-switcher__option ${code === lang ? "lang-switcher__option--active" : ""}`}
              onClick={() => { onChange(code); setOpen(false); }}
            >{label}</button>
          ))}
        </div>
      )}
    </div>
  );
}

