/* ══════════════════════════════════════════════════════
   Notebook Modal (open note)
══════════════════════════════════════════════════════ */
function NotebookModal({ city, notebook, onClose, onSave }) {
  const [content, setContent] = useState("");

  const handleSubmit = async () =>{
    if(!content.trim()) return;
    await onSubmitEntry(content);
    setContent("");
  };

  return (
    <div className="modal-overlay" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="notebook-page">
        <div className="notebook-page__header">
          <div>{city}のノート</div>
          <button onClick={onClose}>✕</button>
        </div>

        <div className="notebook-page__writing-area">
          <div className="entries-list">
            {entries.length > 0 ? (
              entries.map((entry) => (
                <div key={entry.id} className="entry-card">
                  <div className="entry-date">{entry.created_at}</div>
                  <div className="entry-content">{entry.content}</div>
                </div>
              ))
            ) : (
              <p>まだ記録はありません。</p>
            )}
          </div>

          <textarea
            className="notebook-page__textarea"
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="この場所の思い出を書いてください"
          />

          <button onClick={handleSubmit}>投稿</button>
        </div>
      </div>
    </div>
  )
}

/* ══════════════════════════════════════════════════════
   Meadow Scene
══════════════════════════════════════════════════════ */
function MeadowScene({ notebooks, onOpenBook, loadedStorage, phase, t }) {
  const cities = Object.keys(notebooks);

  return (
    <div className="meadow">
      {/* photo background */}
      <div className="meadow__bg" style={{ backgroundImage: `url(${BG_IMAGE})` }} />

      {/* soft vignette overlay */}
      <div className="meadow__vignette" />

      {/* dreamy haze near horizon */}
      <div className="meadow__haze" />

      {/* wind lines drifting across grass */}
      {[...Array(5)].map((_, i) => (
        <div key={i} className="meadow__wind" style={{
          top: `${55 + i * 6}%`,
          "--wind-delay": `${i * 1.2}s`,
          "--wind-dur": `${3.5 + i * 0.6}s`,
        }} />
      ))}

      {/* floating seeds / dandelions */}
      {[...Array(8)].map((_, i) => (
        <div key={i} className="meadow__seed" style={{
          left: `${8 + i * 11}%`,
          "--seed-delay": `${i * 1.4}s`,
          "--seed-dur":   `${7 + i * 1.1}s`,
          "--seed-drift": `${(i % 2 === 0 ? 1 : -1) * (20 + i * 8)}px`,
        }} />
      ))}

      {/* Books in the meadow */}
      <div className="meadow__books">
        {loadedStorage && cities.length > 0 ? (
          cities.map((city, i) => (
            <Book
              key={city}
              city={city}
              notebook={notebooks[city]}
              onOpen={() => onOpenBook(city)}
              index={i}
              total={cities.length}
            />
          ))
        ) : loadedStorage && phase !== "locating" ? (
          <p className="meadow__hint">{t.emptyHint}</p>
        ) : null}
      </div>
    </div>
  );
}

/* ══════════════════════════════════════════════════════
   投稿
══════════════════════════════════════════════════════ */

// GPS取得後、その市町村のノートが無ければ作る
async function getOrCreatePlace(placeInfo) {
  const { cityKey, city, prefecture, country, lat, lng } = placeInfo;

  const { data: existing, error: findError } = await supabase
    .from("places")
    .select("*")
    .eq("city_key", cityKey)
    .maybeSingle();

  if (findError) throw findError;
  if (existing) return existing;

  const { data: inserted, error: insertError } = await supabase
    .from("places")
    .insert({
      city_key: cityKey,
      city,
      prefecture,
      country,
      lat,
      lng,
    })
    .select()
    .single();

  if (insertError) throw insertError;
  return inserted;
}

// 投稿取得関数
async function fetchPlaceEntries(placeId) {
  const { data, error } = await supabase
    .from("place_entries")
    .select("*")
    .eq("place_id", placeId)
    .order("created_at", { ascending: false });

  if (error) throw error;
  return data || [];
}

// 投稿関数
async function addPlaceEntry(placeId, content, authorName = null) {
  const { data, error } = await supabase
    .from("place_entries")
    .insert({
      place_id: placeId,
      content,
      author_name: authorName,
    })
    .select()
    .single();

  if (error) throw error;
  return data;
}




/* ══════════════════════════════════════════════════════
   Main App
══════════════════════════════════════════════════════ */
export default function App() {
  const [lang, setLang]                   = useState("en");
  const [phase, setPhase]                 = useState("idle");
  const [currentCity, setCurrentCity]     = useState(null);
  const [notebooks, setNotebooks]         = useState({});
  const [errorMsg, setErrorMsg]           = useState("");
  const [loadedStorage, setLoadedStorage] = useState(false);
  const [openCity, setOpenCity]           = useState(null);

  const [currentPlace, setCurrentPlace] = useState(null);
  const [entries, setEntries] = useState([]);
  const [places, setPlaces] = useState({});

  const t = TRANSLATIONS[lang];

  useEffect(() => {
    Promise.all([loadAllNotebooks(), loadLang()]).then(([data, savedLang]) => {
      setNotebooks(data);
      setLang(savedLang);
      setLoadedStorage(true);
    });
  }, []);

  const handleLangChange = (code) => { setLang(code); saveLang(code); };

  // submit関数
  const handleSubmitEntry = async (content) => {
    if (!currentPlace) return;

    const newEntry = await addPlaceEntry(currentPlace.id, content, null);
    setEntries((prev) => [newEntry, ...prev]);
  };

  const handleLocate = useCallback(async () => {
    setPhase("locating"); setErrorMsg("");
    // 使えない端末を弾く
    if (!navigator.geolocation) { setErrorMsg(t.errorGeo); setPhase("error"); return; }
    navigator.geolocation.getCurrentPosition(
      // 成功時
      async (pos) => {
        try {
          const placeInfo = await fetchCityName(
            pos.coords.latitude,
            pos.coords.longitude,
            lang
          );

          const place = await getOrCreatePlace(placeInfo);
          const entriesData = await fetchPlaceEntries(place.id);
          setCurrentCity(place.city);
          setCurrentPlace(place);
          setEntries(entriesData);

           setPlaces((prev) => ({
            ...prev,
            [place.city_key]: {
              place,
              entries: entriesData,
            },
          }));

          setPhase("ready");// 本が出現する状態
          /*setOpenCity(city);*/
        } catch { setErrorMsg(t.errorNetwork); setPhase("error"); }
      },
      (err) => {
        setErrorMsg({ 1: t.errorDenied, 2: t.errorUnavailable, 3: t.errorTimeout }[err.code] || t.errorNetwork);
        setPhase("error");
      },
      { timeout: 12000, maximumAge: 60000 }
    );
  }, [lang, t]);

  const handleSave = useCallback((city, content) => {
    setNotebooks((prev) => {
      const next = { ...prev, [city]: { ...prev[city], content, updatedAt: new Date().toLocaleDateString() } };
      saveAllNotebooks(next);
      return next;
    });
  }, []);

  const cityCount = Object.keys(places).length;

  
  // 起動時
  const didAutoLocate = useRef(false); //言語変更で再び走らないように

  useEffect(() => {
    if (!loadedStorage || didAutoLocate.current) return;

    didAutoLocate.current = true;

    const timer = setTimeout(() => {
      handleLocate();
    }, 600);

    return () => clearTimeout(timer);
  }, [loadedStorage, handleLocate]);

  return (
    <LangContext.Provider value={{ lang, t }}>
      <div className="app">

        <div className="lang-switcher-wrap">
          <LangSwitcher lang={lang} onChange={handleLangChange} />
        </div>

        {/* title overlay */}
        <header className="header">
          <p className="header__eyebrow">{t.appEyebrow}</p>
          <h1 className="header__title">{t.appTitle}</h1>
          <div className="header__divider" />
          <p className="header__count">{t.notebookCount(cityCount)}</p>
        </header>

        {/* meadow */}
        <MeadowScene
          notebooks={notebooks}
          onOpenBook={setOpenCity}
          loadedStorage={loadedStorage}
          phase={phase}
          t={t}
        />

        {/* footer UI */}
        <footer className="footer">
          {phase === "error"  && <p className="footer__error">{errorMsg}</p>}
          {phase === "ready" && currentCity && <p className="footer__success">{t.locatedMsg(currentCity)}</p>}

          <button
            className={`locate-btn ${phase === "locating" ? "locate-btn--loading" : "locate-btn--idle"}`}
            onClick={handleLocate}
            disabled={phase === "locating"}
          >
            {phase === "locating" ? (
              <span className="locate-btn__inner"><span className="locate-btn__spinner" />{t.locating}</span>
            ) : (
              <span className="locate-btn__inner">
                <span className="locate-btn__pin">◎</span>
                {t.locateBtn}
                {phase === "idle" && <>
                  <span className="locate-btn__pulse-ring" />
                  <span className="locate-btn__pulse-ring locate-btn__pulse-ring--delayed" />
                </>}
              </span>
            )}
          </button>
          <p className="footer__hint">{t.footerHint}</p>
        </footer>

        {openCity && (
          <NotebookModal
            city={openCity}
            notebook={notebooks[openCity]}
            onClose={() => setOpenCity(null)}
            onSave={handleSave}
          />
        )}
      </div>
    </LangContext.Provider>
  );
}
